import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.Boholvbs.js";const m=JSON.parse('{"title":"Table view","description":"","frontmatter":{},"headers":[],"relativePath":"guide/table.md","filePath":"guide/table.md","lastUpdated":1791661258000}'),r={name:"guide/table.md"};function i(s,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="table-view" tabindex="-1">Table view <a class="header-anchor" href="#table-view" aria-label="Permalink to &quot;Table view&quot;">​</a></h1><p>The table view renders your JSON as a table. Switch to it using the <strong>table</strong> tab in the header (route <code>/table</code>).</p><h2 id="how-the-json-is-rendered" tabindex="-1">How the JSON is rendered <a class="header-anchor" href="#how-the-json-is-rendered" aria-label="Permalink to &quot;How the JSON is rendered&quot;">​</a></h2><ul><li>An <strong>array of objects</strong> becomes one row per element, with a column for every property found in the array.</li><li>An <strong>array of simple values</strong> (strings, numbers, booleans) becomes a single <code>value</code> column.</li><li>A <strong>single object</strong> becomes a list of key/value rows.</li><li><strong>Nested objects and arrays</strong> are shown as smaller tables inside the cell.</li></ul><h2 id="searching-in-the-table" tabindex="-1">Searching in the table <a class="header-anchor" href="#searching-in-the-table" aria-label="Permalink to &quot;Searching in the table&quot;">​</a></h2><ul><li>Type in the search box to filter the rows. The search is case-insensitive and checks every column, including nested values.</li><li>Search a specific column with <code>column:value</code>, for example <code>index:0</code> keeps only the rows where the <code>index</code> column matches <code>0</code>. The column name is matched case-insensitively and can also be abbreviated.</li><li>Matching is fuzzy by default: the characters of the term only need to appear in order, so <code>mse</code> matches <code>Mouse</code>. This works for both the column name and the value.</li><li>Turn on <strong>Exact match</strong> to require the value to be exactly the term (ignoring case) instead of fuzzy matching. For example, <code>index:0</code> with exact match keeps only the rows where the index is <code>0</code>, not <code>10</code>.</li><li>Only the rows that match stay visible. Rows without any match are hidden and <code>No matching data</code> is shown when nothing matches.</li><li>The counter next to the search box shows how many rows are currently displayed (for example <code>2 rows</code>) and updates while you type.</li><li>Use <strong>full screen</strong> to expand the table to the whole page, and exit full screen to go back.</li></ul>',6)])])}const b=t(r,[["render",i]]);export{m as __pageData,b as default};
